var toggle = document.getElementById('sort-toggle')
var list = document.getElementById('sort-list')
var label = document.getElementById('sort-label')
var options = document.querySelectorAll('.dd-option')
var selectedIndex = 0

function updateExpanded() {
  toggle.setAttribute('aria-expanded', list.classList.contains('open'))
}

function focusOption(index) {
  if (index >= 0 && index < options.length) {
    selectedIndex = index
    options[selectedIndex].focus()
  }
}

toggle.addEventListener('click', function () {
  list.classList.toggle('open')
  updateExpanded()
  if (list.classList.contains('open') && options.length > 0) {
    focusOption(0)
  }
})

toggle.addEventListener('keydown', function (e) {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault()
    list.classList.toggle('open')
    updateExpanded()
    if (list.classList.contains('open') && options.length > 0) {
      focusOption(0)
    }
  } else if (e.key === 'Escape') {
    list.classList.remove('open')
    updateExpanded()
    toggle.focus()
  }
})

Array.prototype.forEach.call(options, function (option, index) {
  option.setAttribute('tabindex', '-1')

  option.addEventListener('click', function () {
    label.textContent = 'Sort: ' + option.getAttribute('data-value')
    list.classList.remove('open')
    updateExpanded()
    toggle.focus()
  })

  option.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      label.textContent = 'Sort: ' + option.getAttribute('data-value')
      list.classList.remove('open')
      updateExpanded()
      toggle.focus()
    } else if (e.key === 'Escape') {
      list.classList.remove('open')
      updateExpanded()
      toggle.focus()
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      focusOption((index + 1) % options.length)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      focusOption(index === 0 ? options.length - 1 : index - 1)
    } else if (e.key === 'Home') {
      e.preventDefault()
      focusOption(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      focusOption(options.length - 1)
    }
  })
})

